UPDATE EMP
   SET SAL = SAL + (SELECT MAX(SAL) FROM EMP)
 WHERE DEPT = 10;
SELECT SUM(SAL) AS TOTAL FROM EMP;

DELETE FROM EMP
 WHERE SAL < (SELECT AVG(SAL) FROM EMP);
SELECT COUNT(*) AS CNT FROM EMP;

UPDATE EMP E
   SET DNAME = (SELECT D.DNAME FROM DEPT D WHERE D.DNO = E.DNO);
SELECT COUNT(*) AS CNT, COUNT(DNAME) AS NAMED FROM EMP;

DELETE FROM EMP
 WHERE DNO IN (SELECT DNO FROM DEPT WHERE LOC = 'SEOUL');
SELECT COUNT(*) AS CNT FROM EMP;

