INSERT INTO T_STOCK SELECT ID, QTY FROM S_IN WHERE ID NOT IN (SELECT ID FROM T_STOCK);
UPDATE T_STOCK SET QTY = (SELECT S.QTY FROM S_IN S WHERE S.ID = T_STOCK.ID) WHERE ID IN (SELECT ID FROM S_IN);
DELETE FROM T_STOCK WHERE ID IN (SELECT ID FROM S_IN) AND QTY = 0;
SELECT COUNT(*) AS CNT, SUM(QTY) AS TOTAL FROM T_STOCK;

