INSERT INTO T_ITEM
SELECT ID + 10, QTY FROM T_ITEM WHERE QTY >= 20;
SELECT COUNT(*) AS CNT, SUM(QTY) AS TOTAL FROM T_ITEM;

UPDATE T_ITEM
   SET QTY = CASE WHEN QTY < 20 THEN QTY * 2
                  ELSE QTY - 5 END;
DELETE FROM T_ITEM WHERE QTY < 20;
SELECT COUNT(*) AS CNT, SUM(QTY) AS TOTAL FROM T_ITEM;

DELETE FROM T_NAME X
 WHERE X.ROWID > (SELECT MIN(Y.ROWID)
                    FROM T_NAME Y
                   WHERE Y.NAME = X.NAME);
SELECT COUNT(*) AS CNT FROM T_NAME;
